bad_example:
@external
def add_one(value: uint8) -> uint8:
    return value + 1  # calling with 255 reverts

good_example:
@external
def add_one(value: uint8) -> uint8:
    assert value < 255
    return value + 1

bad_example:
module demo::coin {
  struct Coin has key { value: u64 }
  fun duplicate(c: &Coin): Coin { copy *c }
}

good_example:
module demo::coin {
  struct Coin has key { value: u64 }
  fun consume(c: Coin) { let Coin { value: _ } = c; }
}
